        repo.transact_write(
            [
                repo.build_composite_create(
                    "user-1", "gpt-4", [child], now_ms, cascade=True, parent_id="parent-1"
                )
            ]
        )
        repo._entity_cache.pop((ns, "user-1"), None)
        repo._entity_cache[ns, "parent-1"] = (False, None, {"gpt-4": 2})
